 void performCall(String label,Work work,Done done,boolean guard){if(busy){Toast.makeText(this,"请等待当前请求完成",Toast.LENGTH_SHORT).show();return;}busy=true;long epoch=viewEpoch;status.setTextColor(muted);status.setVisibility(View.VISIBLE);status.setText(label);worker.execute(()->{try{JSONObject j=work.run();runOnUiThread(()->{busy=false;if(guard&&(epoch!=viewEpoch||isFinishing()||isDestroyed()))return;status.setText("");status.setVisibility(View.GONE);try{done.accept(j);}catch(Exception e){error(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{busy=false;if(guard&&(epoch!=viewEpoch||isFinishing()||isDestroyed()))return;if(e instanceof Api.Failure&&((Api.Failure)e).status==401&&!api.token.isEmpty()){store.clear();api.token="";welcome();error("登录已失效，请重新连接。");}else error(e.getMessage());});}});} void error(String s){status.setVisibility(View.VISIBLE);status.setText(s==null?"请求失败":s);status.setTextColor(Color.rgb(170,57,45));Toast.makeText(this,s==null?"请求失败":s,Toast.LENGTH_LONG).show();}
