 void connect(boolean setup){screen(setup?"创建管理员":"连接已有 NAS");body.addView(button("‹ 返回",this::welcome));EditText url=input(body,"服务地址（如 http://192.168.1.10:7120）",api.base,false);body.addView(text("支持局域网与 Tailscale 数字 IP。HTTP 本身不加密；使用 Tailscale 前，手机与 NAS 须登录同一网络。公网请使用 HTTPS。",12,muted));EditText name=input(body,"管理员账号","",false),pass=input(body,"密码","",true),code=input(body,setup?"安装生成的初始化码":"配对码（可代替账号密码）",setupCode,false);body.addView(button(setup?"创建并进入":"连接",()->{if(busy)return;try{api.base=UrlPolicy.normalize(value(url));String p=pass.getText().toString();if(setup&&p.length()<10)throw new Exception("管理员密码至少 10 个字符");String path=setup?"/setup":value(code).isEmpty()?"/login":"/pair";JSONObject payload=setup?json("setup_token",value(code),"username",value(name),"password",p):path.equals("/pair")?json("code",value(code),"label",Build.MODEL):json("username",value(name),"password",p,"label",Build.MODEL);call("正在连接…",()->api.request("POST",path,payload),j->{store.save(api.base,j.getString("token"));api.token=j.getString("token");pass.setText("");code.setText("");setupCode="";home();});}catch(Exception e){error(e.getMessage());}}));if(!setup)body.addView(button("首次安装：创建管理员",()->{if(busy)return;try{api.base=UrlPolicy.normalize(value(url));connect(true);}catch(Exception e){error(e.getMessage());}}));}
 void home(){screen("下载任务");LinearLayout actions=row();weight(actions,button("＋ 添加",this::addTask));weight(actions,button("站点搜索",this::siteSearch));weight(actions,button("刷新",()->loadTasks(true)));weight(actions,button("更多",this::menu));body.addView(actions);select=new Spinner(this);body.addView(select);search=new EditText(this);search.setSingleLine(true);search.setHint("搜索任务名称");search.setTextSize(14);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);search.setOnEditorActionListener((v,a,e)->{loadTasks(true);return true;});body.addView(search);tabRow=row();body.addView(tabRow);summary=text("",13,muted);body.addView(summary);scroll.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){touchX=e.getX();touchY=e.getY();}else if(e.getAction()==MotionEvent.ACTION_UP){float dx=e.getX()-touchX,dy=e.getY()-touchY;if(Math.abs(dx)>dp(90)&&Math.abs(dx)>Math.abs(dy)*1.5){String[] s={"all","downloading","completed","paused"};int pos=Arrays.asList(s).indexOf(state);state=s[Math.max(0,Math.min(3,pos+(dx<0?1:-1)))];loadTasks(true);}else if(dy>dp(110)&&scroll.getScrollY()==0)loadTasks(true);}return false;});read("读取下载器…",()->api.request("GET","/downloaders",null),j->{downloaders=j.getJSONArray("items");ArrayList<String> names=new ArrayList<>();names.add("全部下载器");for(int i=0;i<downloaders.length();i++)names.add(downloaders.getJSONObject(i).optString("name"));rendering=true;select.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));int index=0;for(int i=0;i<downloaders.length();i++)if(downloaders.getJSONObject(i).optString("id").equals(chosen))index=i+1;if(index==0)chosen="all";select.setSelection(index);rendering=false;select.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){String next=n==0?"all":downloaders.optJSONObject(n-1).optString("id");if(!rendering&&!next.equals(chosen)){chosen=next;loadTasks(true);}}});loadTasks(true);});}
 int fixedChildren=5;
 void loadTasks(boolean reset){if(search==null)return;String requestedState=state,requestedDownloader=chosen,requestedQuery=value(search);if(reset)offset=0;String q="/tasks?downloader_id="+Api.segment(chosen)+"&state="+state+"&query="+Api.segment(value(search))+"&offset="+offset+"&limit=50";read("读取任务…",()->api.request("GET",q,null),j->{if(!requestedState.equals(state)||!requestedDownloader.equals(chosen)||!requestedQuery.equals(value(search))){loadTasks(true);return;}while(body.getChildCount()>fixedChildren)body.removeViewAt(fixedChildren);total=j.optInt("total");JSONObject sums=j.optJSONObject("summary");if(sums==null)sums=new JSONObject();tabRow.removeAllViews();String[] ids={"all","downloading","completed","paused"},labels={"全部","下载","完成","暂停"};for(int i=0;i<ids.length;i++){final String s=ids[i];Button b=button(labels[i]+" "+sums.optInt(s.equals("all")?"total":s),()->{state=s;loadTasks(true);});b.setTextSize(12);b.setSingleLine();if(state.equals(s)){b.setTypeface(null,Typeface.BOLD);b.setTextColor(ink);b.setBackground(shape(0xffdaeee7));}weight(tabRow,b);}summary.setText("↓ "+bytes(sums.optDouble("download_speed"))+"/s   ↑ "+bytes(sums.optDouble("upload_speed"))+"/s   共 "+total+" 项");JSONArray errors=j.optJSONArray("errors");if(errors!=null)for(int i=0;i<errors.length();i++)body.addView(text(errors.getJSONObject(i).optString("error"),13,Color.RED));JSONArray items=j.optJSONArray("items");if(items==null||items.length()==0){body.addView(text(downloaders.length()==0?"还没有下载器，请在“更多 → 下载器管理”中添加并验证连接。":"此分类没有任务。可切换“全部”，或使用“添加”导入磁力链接 / 种子。",15,muted));}else for(int i=0;i<items.length();i++)taskCard(items.getJSONObject(i));LinearLayout paging=row();if(offset>0)weight(paging,button("上一页",()->{offset=Math.max(0,offset-50);loadTasks(false);}));if(offset+50<total)weight(paging,button("下一页",()->{offset+=50;loadTasks(false);}));body.addView(paging);body.setAlpha(.35f);body.animate().alpha(1).setDuration(180).start();});}
 static String bytes(double n){if(Double.isNaN(n)||Double.isInfinite(n)||n<0)n=0;if(n<1024)return String.format(Locale.US,"%.0f B",n);String[] u={"KB","MB","GB","TB"};n/=1024;int i=0;while(n>=1024&&i<3){n/=1024;i++;}return String.format(Locale.US,"%.1f %s",n,u[i]);}
 String taskId(JSONObject t){return t.optString("id",t.optString("hash"));}String downloaderId(JSONObject t){return t.optString("downloader_id",chosen);}
 String stateLabel(String s){switch(s){case "downloading":return "下载中";case "paused":return "已暂停";case "completed":return "已完成";case "seeding":return "做种中";case "checking":return "校验中";case "queued":return "排队中";case "error":return "错误";default:return s.isEmpty()?"状态未知":s;}}
 void taskCard(JSONObject t){LinearLayout c=card();TextView name=text(t.optString("name","未命名任务"),16,ink);name.setTypeface(null,Typeface.BOLD);c.addView(name);double p=t.optDouble("progress",0);if(p>1)p/=100;p=Math.max(0,Math.min(1,p));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)(p*1000));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(green));c.addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));c.addView(text(t.optString("state_label",stateLabel(t.optString("state")))+" · "+String.format(Locale.US,"%.1f%%",p*100)+" · "+bytes(t.optDouble("size",t.optDouble("total_size"))),13,muted));c.addView(text("↓ "+bytes(t.optDouble("download_speed"))+"/s   ↑ "+bytes(t.optDouble("upload_speed"))+"/s",13,muted));c.setOnClickListener(v->detail(t));body.addView(c);}
 void detail(JSONObject task){String path="/tasks/"+Api.segment(downloaderId(task))+"/"+Api.segment(taskId(task));read("读取任务详情…",()->api.request("GET",path,null),j->{LinearLayout f=col();JSONObject t=j.optJSONObject("item");if(t==null)t=task;f.addView(text(t.optString("name"),18,ink));f.addView(text(t.optString("state_label",stateLabel(t.optString("state")))+" · "+bytes(t.optDouble("total_size",t.optDouble("size",0)))+"\n保存目录："+t.optString("save_path","未提供"),13,muted));LinearLayout buttons=row();boolean paused=t.optString("state").equals("paused");String control=paused?"继续":t.optString("state").equals("completed")||t.optDouble("progress",0)>=1?"暂停做种":"暂停下载";weight(buttons,button(control,()->action(task,paused?"resume":"pause",false)));weight(buttons,button("删除",()->deleteTask(task)));f.addView(buttons);f.addView(text("文件",16,ink));JSONArray files=j.optJSONArray("files");if(files!=null)for(int i=0;i<files.length();i++){JSONObject item=files.getJSONObject(i);f.addView(text(item.optString("name")+"\n"+bytes(item.optDouble("size"))+" · "+String.format(Locale.US,"%.1f%%",item.optDouble("progress",0)*100),13,muted));}f.addView(text("Tracker",16,ink));JSONArray tr=j.optJSONArray("trackers");if(tr!=null)for(int i=0;i<tr.length();i++){JSONObject x=tr.getJSONObject(i);f.addView(text(x.optString("url")+"\n"+x.optString("status")+" "+x.optString("message"),12,muted));}dialog("任务详情",f,null,null);});}
 void deleteTask(JSONObject t){LinearLayout f=col();f.addView(text("从下载器删除“"+t.optString("name")+"”？",15,ink));CheckBox data=new CheckBox(this);data.setText("同时删除下载文件（不可恢复）");f.addView(data);dialog("删除任务",f,"删除",()->action(t,"delete",data.isChecked()));}
 void action(JSONObject t,String action,boolean deleteData){try{mutate("/tasks/"+Api.segment(downloaderId(t))+"/"+Api.segment(taskId(t))+"/action",json("action",action,"delete_data",deleteData));}catch(Exception e){error(e.getMessage());}}
 static String canonical(Object value)throws Exception {
  if(value instanceof JSONObject){JSONObject j=(JSONObject)value;TreeSet<String> keys=new TreeSet<>();Iterator<String> iterator=j.keys();while(iterator.hasNext()){String key=iterator.next();if(!key.equals("request_id"))keys.add(key);}StringBuilder out=new StringBuilder("{");for(String key:keys){if(out.length()>1)out.append(',');out.append(JSONObject.quote(key)).append(':').append(canonical(j.get(key)));}return out.append('}').toString();}
  if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int i=0;i<a.length();i++){if(i>0)out.append(',');out.append(canonical(a.get(i)));}return out.append(']').toString();}
  if(value==null||value==JSONObject.NULL)return "null";if(value instanceof String)return JSONObject.quote((String)value);return value.toString();
 }
 String signature(String path,JSONObject payload)throws Exception {byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest((api.base+"\n"+path+"\n"+canonical(payload)).getBytes("UTF-8"));return "sig:"+android.util.Base64.encodeToString(digest,android.util.Base64.NO_WRAP);}
 void clearReceipt(String id){android.content.SharedPreferences p=getSharedPreferences("operations",0);android.content.SharedPreferences.Editor e=p.edit().remove(id);for(Map.Entry<String,?> x:p.getAll().entrySet())if(x.getKey().startsWith("sig:")&&id.equals(x.getValue()))e.remove(x.getKey());e.commit();}
 void mutate(String path,JSONObject payload)throws Exception {
  if(busy)throw new Exception("请等待当前请求完成");android.content.SharedPreferences p=getSharedPreferences("operations",0);String sig=signature(path,payload),known=p.getString(sig,"");
  if(!known.isEmpty()){receipt(known);return;}
  String id=UUID.randomUUID().toString();payload.put("request_id",id);
  if(!p.edit().putString(id,api.base).putString(sig,id).commit())throw new Exception("无法保存操作编号，未发送请求");
  call("提交操作…",()->{try{return api.request("POST",path,payload);}catch(Exception first){if(first instanceof Api.Failure&&((Api.Failure)first).status>=400&&((Api.Failure)first).status<500){clearReceipt(id);throw first;}try{return api.request("GET","/operations/"+id,null);}catch(Exception second){return json("ok",true,"operation",json("request_id",id,"status","uncertain","message","响应未知。请在操作记录中查询回执，不要重复添加或删除。"));}}},j->{JSONObject op=j.optJSONObject("operation");if(op!=null&&"completed".equals(op.optString("status")))clearReceipt(id);String msg=op==null?"已提交":op.optString("message",op.optString("status"));new AlertDialog.Builder(this).setTitle("操作回执").setMessage(msg+"\n编号："+id).setPositiveButton("确定",(d,w)->{if(path.startsWith("/sites/"))home();else loadTasks(true);}).show();});
 } void dialog(String title,LinearLayout form,String positive,Runnable action){ScrollView sv=new ScrollView(this);form.setPadding(dp(18),dp(8),dp(18),dp(8));sv.addView(form);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(title).setView(sv).setNegativeButton("关闭",null);if(positive!=null)b.setPositiveButton(positive,null);AlertDialog d=b.create();d.show();if(positive!=null)d.getButton(-1).setOnClickListener(v->{action.run();if(busy)d.dismiss();});}
 void addTask(){if(downloaders.length()==0){error("请先添加下载器");return;}torrent=null;LinearLayout f=col();Spinner d=new Spinner(this);ArrayList<String> names=new ArrayList<>();int ix=0;for(int i=0;i<downloaders.length();i++){JSONObject x=downloaders.optJSONObject(i);names.add(x.optString("name"));if(x.optString("id").equals(chosen))ix=i;}d.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));d.setSelection(ix);f.addView(d);EditText url=input(f,"磁力链接 / 种子 URL","",false),save=input(f,"保存目录（留空使用下载器默认值）","",false);torrentLabel=text("未选择种子文件",13,muted);f.addView(torrentLabel);f.addView(button("选择 .torrent 文件",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,9);}));CheckBox paused=new CheckBox(this);paused.setText("添加后暂停");f.addView(paused);dialog("添加下载",f,"添加",()->{try{if(torrent==null&&value(url).isEmpty())throw new Exception("请输入链接或选择种子文件");JSONObject x=json("downloader_id",downloaders.getJSONObject(d.getSelectedItemPosition()).getString("id"),"paused",paused.isChecked());if(torrent!=null)x.put("torrent_base64",android.util.Base64.encodeToString(torrent,android.util.Base64.NO_WRAP));else x.put("url",value(url));if(!value(save).isEmpty())x.put("save_path",value(save));mutate("/tasks/add",x);}catch(Exception e){error(e.getMessage());Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==9&&c==RESULT_OK&&data!=null){try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(b.size()+n>2*1024*1024)throw new Exception("种子文件不能超过 2 MB");b.write(buf,0,n);}torrent=b.toByteArray();torrentLabel.setText("已选择种子 · "+bytes(torrent.length));}catch(Exception e){error(e.getMessage());}}}
