 void downloaderForm(JSONObject old){LinearLayout f=col();Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"qBittorrent","Transmission"}));type.setSelection(old!=null&&old.optString("type").equals("transmission")?1:0);f.addView(type);EditText name=input(f,"名称",old==null?"":old.optString("name"),false),url=input(f,"下载器地址",old==null?"":old.optString("url"),false),user=input(f,"用户名","",false),pass=input(f,"密码（编辑留空保持原密码）","",true),save=input(f,"默认保存目录",old==null?"":old.optString("default_save_path"),false);f.addView(text("地址由 NAS 服务访问；下载器账号密码由服务端加密保存，手机不保存。",12,muted));Runnable test=()->{try{JSONObject p=downloaderPayload(type,name,url,user,pass,save,old);if(old!=null)p.put("downloader_id",old.get("id"));call("测试连接…",()->api.request("POST","/downloaders/test",p),j->new AlertDialog.Builder(this).setMessage("连接成功 · "+j.optString("version")).setPositiveButton("确定",null).show());}catch(Exception e){error(e.getMessage());}};f.addView(button("测试连接",test));if(old!=null)f.addView(button("移除接入",()->new AlertDialog.Builder(this).setMessage("移除该下载器接入？下载任务不会删除。").setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->call("移除接入…",()->api.request("DELETE","/downloaders/"+Api.segment(old.optString("id")),null),j->home())).show()));dialog(old==null?"添加下载器":"编辑下载器",f,"保存",()->{try{JSONObject p=downloaderPayload(type,name,url,user,pass,save,old);call("验证并保存…",()->api.request(old==null?"POST":"PATCH",old==null?"/downloaders":"/downloaders/"+Api.segment(old.optString("id")),p),j->{pass.setText("");home();});}catch(Exception e){error(e.getMessage());}});}
