 void installForm(){screen("自动安装");body.addView(button("‹ 返回",this::welcome));body.addView(text("安装一个 Nas Download 产品，自带下载能力。当前 SSH 账号必须已能运行 Docker Compose；不自动安装 Docker，也不提权。",13,muted));EditText host=input(body,"SSH 主机（IP / 主机名）","",false),port=input(body,"SSH 端口","22",false),user=input(body,"SSH 用户名","",false),pass=input(body,"SSH 密码（只在内存使用）","",true),dir=input(body,"安装目录（绝对路径）","/volume1/docker/nas-download",false),bind=input(body,"服务监听地址","0.0.0.0",false);EditText servicePort=input(body,"服务端口（1024–65534）","7120",false);servicePort.setInputType(InputType.TYPE_CLASS_NUMBER);Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"内置下载（推荐）","高级：接入已有下载器"}));body.addView(mode);EditText downloads=input(body,"下载保存目录（可留空）","",false);body.addView(text("首次连接必须核对 NAS 的 SSH 主机指纹。监听 0.0.0.0 允许局域网访问；请勿将服务端口映射到公网。",12,muted));body.addView(button("验证并安装",()->{if(busy)return;try{String h=value(host),u=value(user),secret=pass.getText().toString(),folder=value(dir),b=value(bind),down=value(downloads),installMode=UrlPolicy.installMode(mode.getSelectedItemPosition());int sp=Integer.parseInt(value(servicePort));UrlPolicy.servicePort(sp);int p=Integer.parseInt(value(port));if(p<1||p>65535||h.isEmpty()||u.isEmpty()||secret.isEmpty())throw new Exception("请完整填写 SSH 连接信息");UrlPolicy.absoluteDir(folder);busy=true;long installEpoch=viewEpoch;pass.setText("");status.setVisibility(View.VISIBLE);status.setText("连接 SSH…");worker.execute(()->{try{String out=SshInstaller.install(this,h,p,u,secret,folder,b,sp,down,installMode,(identity,fp)->confirmHost(identity,fp),msg->runOnUiThread(()->{if(installEpoch==viewEpoch&&!isFinishing()&&!isDestroyed())status.setText(msg);}));InstallerResult installed=InstallerResult.parse(out,h,sp);String resultUrl=installed.url,resultCode=installed.setupCode;runOnUiThread(()->{busy=false;if(installEpoch!=viewEpoch||isFinishing()||isDestroyed())return;try{api.base=UrlPolicy.normalize(resultUrl.replace("<host>",h).replace("0.0.0.0",h));setupCode=resultCode;if(setupCode.isEmpty()){status.setText("服务安装已完成。未返回初始化码，请检查安装目录中的首次配置说明。");connect(false);}else connect(true);}catch(Exception e){error("服务已安装，但自动连接失败。请手动连接：http://"+h+":"+sp);}});}catch(Exception e){runOnUiThread(()->{busy=false;if(installEpoch!=viewEpoch||isFinishing()||isDestroyed())return;error("安装未完成："+e.getMessage());});}});}catch(Exception e){error(e.getMessage());}}));}
 boolean confirmHost(String identity,String fingerprint){CountDownLatch latch=new CountDownLatch(1);boolean[] yes={false};runOnUiThread(()->new AlertDialog.Builder(this).setTitle("确认 NAS 的 SSH 指纹").setMessage(identity+"\n\n"+fingerprint+"\n\n请与 NAS 的 SSH 主机公钥指纹核对。确认后保存；后续指纹变化会拒绝连接。").setCancelable(false).setNegativeButton("取消",(d,w)->latch.countDown()).setPositiveButton("已核对，信任",(d,w)->{yes[0]=true;latch.countDown();}).show());try{if(!latch.await(5,TimeUnit.MINUTES))return false;}catch(InterruptedException e){return false;}return yes[0];}
 @Override protected void onDestroy(){viewEpoch++;worker.shutdownNow();super.onDestroy();}

