 void siteForm(JSONObject old){LinearLayout f=col();EditText name=input(f,"名称",old==null?"":old.optString("name"),false);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"M-Team","Torznab / Jackett / Prowlarr"}));type.setSelection(old!=null&&old.optString("type").equals("torznab")?1:0);f.addView(type);EditText url=input(f,"完整 API 地址（HTTPS）",old==null?"":old.optString("url"),false),key=input(f,"API Key（修改时留空保留）","",true);f.addView(text("M-Team：https://api.m-team.cc/api；其他站点填写 Torznab API 完整路径。",12,muted));CheckBox enabled=new CheckBox(this);enabled.setText("启用搜索");enabled.setChecked(old==null||old.optBoolean("enabled"));f.addView(enabled);if(old!=null)f.addView(button("移除此站点",()->new AlertDialog.Builder(this).setMessage("移除站点配置？下载任务仍保留。").setPositiveButton("移除",(d,w)->call("移除站点…",()->api.request("DELETE","/sites/"+Api.segment(old.optString("id")),null),j->siteManage())).setNegativeButton("取消",null).show()));dialog("站点配置",f,"保存",()->{try{JSONObject x=json("name",value(name),"type",type.getSelectedItemPosition()==0?"mteam":"torznab","url",value(url),"enabled",enabled.isChecked());if(!value(key).isEmpty())x.put("api_key",value(key));call("保存站点…",()->api.request(old==null?"POST":"PATCH",old==null?"/sites":"/sites/"+Api.segment(old.optString("id")),x),j->{key.setText("");siteManage();});}catch(Exception e){error(e.getMessage());}});}
 String activeSearch="";long searchIntent;int sitePage=1;EditText siteQuery;LinearLayout siteResults;
 void siteSearch(){screen("站点搜索");body.addView(button("‹ 下载任务",()->{cancelSiteSearch();home();}));body.addView(button("站点配置",()->{cancelSiteSearch();siteManage();}));siteQuery=input(body,"关键词（搜索已启用站点）","",false);body.addView(button("搜索",()->startSiteSearch(1)));body.addView(button("停止当前搜索",()->{if(activeSearch.isEmpty()){error("当前没有搜索");return;}String id=activeSearch;call("停止搜索…",()->api.request("DELETE","/searches/"+Api.segment(id),null),j->{activeSearch="";status.setText("搜索已停止");});}));siteResults=col();body.addView(siteResults);siteResults.addView(text("先配置自己的站点 API Key，再输入关键词搜索。站点故障会单独显示。",14,muted));}
 void startSiteSearch(int page){if(busy){error("请等待当前请求完成");return;}final String query=value(siteQuery);if(query.isEmpty()){error("请输入关键词");return;}final long epoch=viewEpoch,intent=++searchIntent;final EditText requestedInput=siteQuery;final String old=activeSearch;sitePage=page;busy=true;status.setVisibility(View.VISIBLE);status.setTextColor(muted);status.setText("开始搜索…");worker.execute(()->{try{if(!old.isEmpty())api.request("DELETE","/searches/"+Api.segment(old),null);JSONObject result=api.request("POST","/searches",json("query",query,"page",page,"limit",30));String id=result.getString("search_id");runOnUiThread(()->{busy=false;if(epoch!=viewEpoch||intent!=searchIntent||requestedInput!=siteQuery||!query.equals(value(requestedInput))||isFinishing()||isDestroyed()){cancelSearchId(id);return;}activeSearch=id;status.setVisibility(View.GONE);siteResults.removeAllViews();pollSiteSearch(id,epoch);});}catch(Exception e){runOnUiThread(()->{busy=false;if(epoch==viewEpoch&&intent==searchIntent&&!isFinishing()&&!isDestroyed())error(e.getMessage());});}});}
 void pollSiteSearch(String id,long epoch){if(epoch!=viewEpoch||!id.equals(activeSearch))return;if(busy){new Handler(getMainLooper()).postDelayed(()->pollSiteSearch(id,epoch),1000);return;}read("搜索中…",()->{JSONObject result=api.request("GET","/searches/"+Api.segment(id)+"?offset=0&limit=100",null);if(!result.optString("status").equals("running")){JSONArray all=result.optJSONArray("items");if(all!=null){int fetched=all.length(),count=result.optInt("total");while(fetched<count){JSONObject batch=api.request("GET","/searches/"+Api.segment(id)+"?offset="+fetched+"&limit=100",null);JSONArray more=batch.optJSONArray("items");if(more==null||more.length()==0)break;for(int i=0;i<more.length();i++)all.put(more.get(i));fetched=all.length();}}}return result;},j->{if(epoch!=viewEpoch||!id.equals(activeSearch))return;siteResults.removeAllViews();JSONArray errors=j.optJSONArray("errors");if(errors!=null)for(int i=0;i<errors.length();i++){JSONObject e=errors.optJSONObject(i);siteResults.addView(text(e==null?errors.optString(i):e.optString("site_name",e.optString("site_id"))+"："+e.optString("error"),13,Color.RED));}JSONArray a=j.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);LinearLayout c=card();c.addView(text(x.optString("name"),16,ink));c.addView(text(x.optString("site_name")+" · "+bytes(x.optDouble("size"))+" · 做种 "+x.optInt("seeders")+" · "+x.optString("promotion"),12,muted));c.addView(button("详情 / 下载",()->siteDetail(x)));siteResults.addView(c);}String st=j.optString("status");if(st.equals("running")){siteResults.addView(text("正在查询站点…",13,muted));new Handler(getMainLooper()).postDelayed(()->pollSiteSearch(id,epoch),1200);}else{activeSearch="";if(a==null||a.length()==0)siteResults.addView(text(st.equals("cancelled")?"搜索已停止":"没有匹配结果。请检查关键词、站点启用状态和 API Key。",14,muted));LinearLayout paging=row();if(sitePage>1)weight(paging,button("上一页",()->startSiteSearch(sitePage-1)));if(a!=null&&a.length()>0&&hasSiteNext(j))weight(paging,button("下一页",()->startSiteSearch(sitePage+1)));siteResults.addView(paging);}});}
 boolean hasSiteNext(JSONObject j){JSONObject totals=j.optJSONObject("site_totals");if(totals==null)return false;Iterator<String> keys=totals.keys();while(keys.hasNext())if(totals.optInt(keys.next())>sitePage*30)return true;return false;}
 void cancelSiteSearch(){searchIntent++;String id=activeSearch;activeSearch="";cancelSearchId(id);}
 void cancelSearchId(String id){if(!id.isEmpty())worker.execute(()->{try{api.request("DELETE","/searches/"+Api.segment(id),null);}catch(Exception ignored){}});}
