 void siteDownload(String path,JSONObject item){if(downloaders.length()==0){error("请返回下载任务，在更多中添加下载器");return;}LinearLayout f=col();f.addView(text(item.optString("name"),15,ink));Spinner d=new Spinner(this);ArrayList<String> names=new ArrayList<>();for(int i=0;i<downloaders.length();i++)names.add(downloaders.optJSONObject(i).optString("name"));d.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));f.addView(d);EditText save=input(f,"保存目录（留空使用默认值）","",false);CheckBox paused=new CheckBox(this);paused.setText("添加后暂停");f.addView(paused);dialog("添加站点种子",f,"下载",()->{try{JSONObject payload=json("downloader_id",downloaders.getJSONObject(d.getSelectedItemPosition()).getString("id"),"paused",paused.isChecked());if(!value(save).isEmpty())payload.put("save_path",value(save));mutate(path+"/download",payload);}catch(Exception e){error(e.getMessage());}});}
